/**
 * Verify the request actually came from Koya Lead Desk.
 *
 * The webhook URL is not a secret. It sits in an environment variable, in a
 * deploy log, and in this workflow's own definition, so the URL alone must
 * not be enough to make this workflow post into the team's Discord. A channel
 * that can be spoofed is worse than no channel, because people trust what it
 * says.
 *
 * THIS NODE RETURNS A VERDICT RATHER THAN THROWING, and is set to continue on
 * error. A throw here kills the workflow before the respond node runs, so the
 * app sees a generic 500 and cannot tell a rejected signature from n8n being
 * broken. The `Verified?` gate turns the verdict below into a 401 the app can
 * record and a human can read.
 */
const crypto = require('crypto');

const SECRET_NAME = 'KOYA_LEAD_NOTIFY_SECRET';

/**
 * Where the shared secret comes from, and why this is not a one-liner.
 *
 * `$env` is not available on every n8n instance. n8n Cloud has no process
 * environment a workflow can reach, and self-hosted instances ship with
 * N8N_BLOCK_ENV_ACCESS_IN_NODE=true by default. On both, TOUCHING `$env`
 * THROWS rather than returning undefined, so a bare `$env.FOO` would kill the
 * node before the fail-closed branch below could run.
 */
function readSecret(name) {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]);
  } catch (err) {
    // Env access is blocked on this instance. Not fatal, try Variables.
  }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return String($vars[name]);
  } catch (err) {
    // Neither source is readable. Handled by the fail-closed branch below.
  }
  return null;
}

const secret = readSecret(SECRET_NAME);
if (!secret) {
  // Failing closed. A missing secret must never mean "skip the check".
  return [{ json: { ok: false, status: 401, reason:
    SECRET_NAME + ' is not readable on this n8n instance. Set it as a Variable ' +
    '(Settings > Variables), or as an environment variable with ' +
    'N8N_BLOCK_ENV_ACCESS_IN_NODE=false. Its value must match ' +
    'N8N_LEAD_NOTIFY_SECRET in the application.' } }];
}

const TOLERANCE_SECONDS = 300;

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-koya-signature'];
const timestamp = headers['x-koya-timestamp'];
if (!signature || !timestamp) {
  return [{ json: { ok: false, status: 401, reason: 'missing signature headers' } }];
}

/**
 * The timestamp is inside the signed material, which is what stops a captured
 * request being replayed for ever. Anything outside the window is rejected
 * even when the signature is valid, so a recording of one legitimate
 * notification cannot be used to make this channel repeat it tomorrow.
 */
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) {
  return [{ json: { ok: false, status: 401, reason: 'timestamp outside the ' + TOLERANCE_SECONDS + 's window (age ' + age + 's)' } }];
}

/**
 * Signed over the exact bytes the app sent. The webhook is configured with
 * rawBody so those bytes are available here: re-serialising the parsed body
 * would depend on key order surviving a round trip through two JSON
 * implementations, which is not a thing to bet a security check on.
 */
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body));

const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw, 'utf8').digest('hex');

// Constant time. A byte-by-byte early exit leaks how much of a forged
// signature was correct, which is enough to recover one.
const a = Buffer.from(String(signature), 'utf8');
const b = Buffer.from(expected, 'utf8');
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!valid) {
  return [{ json: { ok: false, status: 401, reason: 'signature mismatch' } }];
}

let payload;
try {
  payload = JSON.parse(raw);
} catch (err) {
  return [{ json: { ok: false, status: 400, reason: 'verified request carried unparseable JSON' } }];
}

// A verified request missing a field is a bug in the caller. Reporting it as
// 400 rather than crashing is what makes it debuggable from the app's own
// notification record.
const required = ['kind', 'level', 'runId', 'title', 'lines'];
const missing = required.filter(function (key) { return !payload[key]; });
if (missing.length > 0) {
  return [{ json: { ok: false, status: 400, reason: 'payload missing: ' + missing.join(', ') } }];
}

return [{
  json: {
    ok: true,
    status: 200,
    kind: payload.kind,
    level: payload.level,
    discordChannel: payload.discordChannel,
    actionRequired: Boolean(payload.actionRequired),
    runId: payload.runId,
    scope: payload.scope || '',
    title: payload.title,
    lines: Array.isArray(payload.lines) ? payload.lines : [],
    recipients: Array.isArray(payload.recipients) ? payload.recipients : [],
    url: payload.url,
    verifiedAt: new Date().toISOString()
  }
}];

/**
 * Gmail refused the message.
 *
 * Discord has already been posted to, but the person who needed telling was
 * not emailed, so this must NOT answer 200. The application treats any
 * non-2xx as a failed primary lane and sends the same notification itself
 * through Resend, recording the result as `degraded` rather than `sent`.
 *
 * That is the whole reason the Resend lane lives in the application and not
 * here: a fallback inside the thing that just failed is not a fallback.
 */
const verified = $('Verify signature').item.json;
const failure = $input.first().json || {};

return [{
  json: {
    ok: false,
    status: 502,
    kind: verified.kind,
    runId: verified.runId,
    reason: 'gmail_failed',
    detail: String(failure.error || failure.message || 'Gmail node reported an error'),
    title: verified.title,
    url: verified.url
  }
}];
